FROM sales WHERE region = 'north';

-- B
SELECT id, pct FROM (
  SELECT id, region, round(100.0 * amount / sum(amount) OVER (), 1) AS pct
  FROM sales
) s
WHERE region = 'north';

-- C
SELECT id, round(100.0 * amount / (SELECT sum(amount) FROM sales), 1) AS pct
FROM sales WHERE region = 'north';

challenges.solution:
SELECT id, round(100.0 * amount / sum(amount) OVER (PARTITION BY region), 1) AS pct
FROM sales
ORDER BY id;

SELECT day, total, total - lag(total) OVER (ORDER BY day) AS change
FROM (SELECT day, sum(amount) AS total FROM sales GROUP BY day) d
ORDER BY day;

SELECT DISTINCT ON (region) region, id, amount
FROM sales
ORDER BY region, amount DESC, id;

